const input=$json.body??$json;
const s=v=>String(v??'').trim();
const id=s(input.deal_id??input.property_id??input.lead_id??input.identity?.deal_id??input.identity?.property_id??input.identity?.lead_id);
const leadId=s(input.lead_id??input.identity?.lead_id);
const propertyId=s(input.property_id??input.identity?.property_id);
const dealId=s(input.deal_id??input.identity?.deal_id);
const propertyType=s(input.property_type??input.asset_type??input.property?.type).toLowerCase();
const address=s(input.property_address??input.property?.address);
const missing=[];
if(!id)missing.push('canonical_identity');
if(!propertyType)missing.push('property_type');
if(!address&&!propertyId)missing.push('property_address_or_property_id');
const tasks=[];
if(!Array.isArray(input.comps)||!input.comps.length)tasks.push({key:'comps',workflow:'wf-071-comps-market-evidence-adapter',required:true});
if(input.arv==null&&input.market_value==null)tasks.push({key:'valuation',workflow:'wf-071-comps-market-evidence-adapter',required:true});
if(input.repairs==null&&input.estimated_repairs==null)tasks.push({key:'repairs',workflow:'wf-072-repair-cost-property-condition-analysis',required:true});
if(!input.property_risk&&!input.risk_evidence)tasks.push({key:'risk',workflow:'wf-073-property-risk-feasibility-analysis',required:true});
if(!input.buyer_demand&&!input.exit_strategy)tasks.push({key:'buyer_demand',workflow:'wf-074-buyer-demand-exit-strategy-analysis',required:true});
const propertySpecific=propertyType.includes('land')||propertyType.includes('vacant');
const evidence={identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},property:{type:propertyType||null,address:address||null},existing:{arv:input.arv??input.market_value??null,market_value:input.market_value??null,repairs:input.repairs??input.estimated_repairs??null,comps:Array.isArray(input.comps)?input.comps:[],property_risk:input.property_risk??input.risk_evidence??null,buyer_demand:input.buyer_demand??null,exit_strategy:input.exit_strategy??null,valuation_available:input.arv!=null||input.market_value!=null,repairs_available:input.repairs!=null||input.estimated_repairs!=null,risk_available:Boolean(input.property_risk||input.risk_evidence),buyer_demand_available:Boolean(input.buyer_demand||input.exit_strategy)},policy:{economic_viability_primary:true,reference_70pct_secondary_only:true,property_type_specific_logic:true,land_specific_logic:propertySpecific}};
const request_id='evidence-orchestration:'+(id||'unknown')+':v1';
const status=missing.length?'needs_context':tasks.length?'evidence_required':'evidence_ready';
return[{json:{ok:missing.length===0,status,request_id,evidence,required_tasks:tasks,orchestration:{next_action:tasks.length?'collect_missing_underwriting_evidence':'send_complete_evidence_to_mao_gate',next_workflow:tasks.length?tasks[0].workflow:'wf-069-deal-viability-mao-strategy-gate',parallelizable_tasks:tasks.map(x=>x.key),all_required_evidence_present:tasks.length===0},identity:evidence.identity,missing_requirements:missing}}];
